14	namespace Maxx.Application.Posts;
15	
16	public interface IPostRepository
17	{
18	    void Adicionar(Post post);
19	
20	    // Inclusive o removido pela instituição: quem remove ou desvincula precisa dele.
21	    Task<Post?> BuscarAsync(Guid id, CancellationToken cancellationToken);
22	
23	    // Os posts do prêmio, removidos ou não. No máximo um não removido, pelo índice único.
24	    Task<IReadOnlyList<Post>> DoPremioAsync(Guid medalhaId, CancellationToken cancellationToken);
25	
26	    // Se o prêmio já rendeu um post que não foi removido.
27	    Task<bool> PremioTemPostAsync(Guid medalhaId, CancellationToken cancellationToken);
28	
29	    // Os posts do prêmio de participação, removidos ou não.
30	    Task<IReadOnlyList<Post>> DoPremioParticipacaoAsync(Guid premioId, CancellationToken cancellationToken);
31	
32	    // Os posts da conquista, removidos ou não (passo 9).
33	    Task<IReadOnlyList<Post>> DaConquistaAsync(Guid conquistaId, CancellationToken cancellationToken);
34	
35	    // Se a conquista já rendeu um post que não foi removido.
36	    Task<bool> ConquistaTemPostAsync(Guid conquistaId, CancellationToken cancellationToken);
37	
38	    void Apagar(Post post);
39	}
40	
41	// O post como o app mostra: autor com curso e semestre, a foto, o prêmio com tier, pontos
42	// do momento e raridade atual. Só consulta, sem regra.
43	public interface IConsultaDePosts
44	{
45	    // Nulo para o que não existe e para o removido pela instituição. Com as curtidas e os
46	    // comentários contados, e se o leitor curtiu.
47	    Task<PostLido?> PostAsync(Guid id, Guid leitorId, CancellationToken cancellationToken);
48	
49	    // Os que existem e não foram removidos, pelo id; os outros ficam de fora.
50	    Task<IReadOnlyDictionary<Guid, PostLido>> PostsAsync(
51	        IReadOnlyCollection<Guid> ids, Guid leitorId, CancellationToken cancellationToken);
52	}
53	
54	public sealed record PostLido(
55	    Guid Id,
56	    AutorDoPost Autor,
57	    string? Legenda,
58	    string? ChaveDaFotoDoFeed,
59	    string? ChaveDaFotoDaGrade,
60	    PremioDoPost? Premio,
61	    DateTimeOffset CriadoEm,
62	    int Curtidas,
63	    int Comentarios,
64	    bool Curtiu);
65	
66	// Curso e semestre do aluno são perfil (produto.md 3); o RA nunca sai daqui.
67	// A foto é a derivada da grade (~320²), que basta para o avatar. A posição é a do histórico
68	// geral, como no perfil (passo 11): vem no post do feed e do perfil; nas filas de
69	// comprovação e de contestação, nula.
70	public sealed record AutorDoPost(
71	    Guid Id, string NomeDeExibicao, string Arroba, string? Curso, int? Semestre, string? ChaveDaFoto, int? Posicao = null);
72	
73	// Tier e pontos do momento da concessão (ADR 0007); raridade, a atual. Matéria e bimestre
74	// na medalha; matéria também na apresentação em sala. Estado e evento só no prêmio de
75	// participação (passo 8): reivindicado é a marca de pendente.
76	public sealed record PremioDoPost(
77	    TipoDeItem Tipo,
78	    Guid Id,
79	    string Item,
80	    string Nome,
81	    Tier Tier,
82	    int Pontos,
83	    RaridadeAtual? Raridade,
84	    string? Materia,
85	    int? Bimestre,
86	    EstadoDoPremioParticipacao? Estado = null,
87	    string? Evento = null);
88	
89	// Publicação de post (produto.md 6.1). As regras são do domínio; aqui, buscar o que o
90	// pedido cita, conferir no bucket que a foto chegou e gravar. A corrida de dois posts com o
91	// mesmo prêmio é do índice único; a de dois posts com a mesma foto, do xmin do upload.
92	public sealed class PublicarPostHandler(
93	    IUsuarioRepository usuarios,
94	    IUploadPendenteRepository uploads,
95	    IMedalhaRepository medalhas,
96	    IConquistaRepository conquistas,
97	    IPremioParticipacaoRepository premiosDeParticipacao,
98	    IPostRepository posts,
99	    IArmazenamentoDeFotos armazenamento,
100	    IUnitOfWork unitOfWork,
101	    TimeProvider relogio)
102	{
103	    public async Task<Post> PublicarAsync(
104	        Guid autorId, string? legenda, Guid? uploadId, Guid? medalhaId, CancellationToken cancellationToken) =>
105	        await PublicarAsync(autorId, legenda, uploadId, medalhaId, null, cancellationToken);
106	
107	    public async Task<Post> PublicarAsync(
108	        Guid autorId, string? legenda, Guid? uploadId, Guid? medalhaId, Guid? conquistaId, CancellationToken cancellationToken) =>
109	        await PublicarAsync(autorId, legenda, uploadId, medalhaId, conquistaId, null, cancellationToken);
110	
111	    // O prêmio do post é um só: a medalha, a conquista (passo 9) ou o prêmio de participação
112	    // concedido direto pela instituição (passo 12).
113	    public async Task<Post> PublicarAsync(
114	        Guid autorId,
115	        string? legenda,
116	        Guid? uploadId,
117	        Guid? medalhaId,
118	        Guid? conquistaId,
119	        Guid? premioParticipacaoId,
120	        CancellationToken cancellationToken)
121	    {
122	        var autor = await usuarios.BuscarAsync(autorId, cancellationToken)
123	            ?? throw new RecusaException(TipoDeRecusa.NaoAutorizado, CodigosDeRecusa.SessaoInvalida, $"Usuário {autorId} não existe.");
124	
125	        UploadPendente? upload = null;
126	        if (uploadId is { } idDoUpload)
127	        {
128	            upload = await uploads.BuscarAsync(idDoUpload, cancellationToken)
129	                ?? throw Recusa(RecusaDaPublicacao.UploadNaoEncontrado, autorId);
130	        }
131	
132	        Medalha? medalha = null;
133	        if (medalhaId is { } idDaMedalha)
134	        {
135	            medalha = await medalhas.BuscarAsync(idDaMedalha, cancellationToken)
136	                ?? throw Recusa(RecusaDaPublicacao.PremioNaoEncontrado, autorId);
137	        }
138	
139	        Conquista? conquista = null;
140	        if (conquistaId is { } idDaConquista)
141	        {
142	            conquista = await conquistas.BuscarAsync(idDaConquista, cancellationToken)
143	                ?? throw Recusa(RecusaDaPublicacao.PremioNaoEncontrado, autorId);
144	        }
145	
146	        PremioParticipacao? premioParticipacao = null;
147	        if (premioParticipacaoId is { } idDoPremio)
148	        {
149	            premioParticipacao = await premiosDeParticipacao.BuscarAsync(idDoPremio, cancellationToken)
150	                ?? throw Recusa(RecusaDaPublicacao.PremioNaoEncontrado, autorId);
151	        }
152	
153	        var resultado = Post.Publicar(autor, legenda, upload, medalha, conquista, premioParticipacao, relogio.GetUtcNow());
154	        if (resultado.Post is not { } post)
155	        {
156	            throw Recusa(resultado.Recusa!.Value, autorId);
157	        }
158	
159	        var premioId = (medalha?.Id ?? conquista?.Id ?? premioParticipacao?.Id).GetValueOrDefault();
160	        if ((medalha is not null && await posts.PremioTemPostAsync(medalha.Id, cancellationToken))
161	            || (conquista is not null && await posts.ConquistaTemPostAsync(conquista.Id, cancellationToken))
162	            || (premioParticipacao is not null
163	                && (await posts.DoPremioParticipacaoAsync(premioParticipacao.Id, cancellationToken)).Any(existente => !existente.EstaRemovido)))
164	        {
165	            throw PremioJaPostado(premioId);
166	        }
167	
168	        // O app diz que enviou; o bucket confirma. Sem as duas derivadas, o post teria uma
169	        // foto quebrada para sempre.
170	        foreach (var chave in post.ChavesDaFoto)
171	        {
172	            if (!await armazenamento.ExisteAsync(chave, cancellationToken))
173	            {
174	                throw new RecusaException(TipoDeRecusa.Conflito, CodigosDoPost.FotoNaoEnviada, $"Objeto {chave} não chegou ao bucket.");
175	            }
176	        }
177	
178	        posts.Adicionar(post);
179	        try
180	        {
181	            await unitOfWork.SalvarAsync(cancellationToken);
182	        }
183	        catch (ConflitoDeUnicidadeException conflito) when (conflito.Unicidade == Unicidade.PostPorPremio)
184	        {
185	            throw PremioJaPostado(premioId);
186	        }
187	        catch (ConflitoDeConcorrenciaException)
188	        {
189	            // Outro post confirmou o mesmo upload entre a leitura e a gravação.
190	            throw new RecusaException(TipoDeRecusa.Conflito, CodigosDoPost.UploadJaUsado, $"Upload {uploadId} usado ao mesmo tempo.");
191	        }
192	
193	        return post;
194	    }
195	
196	    private static RecusaException PremioJaPostado(Guid premioId) =>
197	        new(TipoDeRecusa.Conflito, CodigosDoPost.PremioJaPostado, $"Prêmio {premioId} já tem post.");
198	
199	    internal static RecusaException Recusa(RecusaDaPublicacao recusa, Guid autorId) => recusa switch
200	    {
201	        RecusaDaPublicacao.AutorNaoPublica => new(TipoDeRecusa.Proibido, CodigosDoPost.PostNaoPermitido, $"{autorId} não publica."),
202	        RecusaDaPublicacao.LegendaLonga => new(TipoDeRecusa.Invalido, CodigosDoPost.LegendaLonga, "Legenda acima do limite."),
203	        RecusaDaPublicacao.Vazio => new(TipoDeRecusa.Invalido, CodigosDoPost.PostVazio, "Post sem prêmio, foto e legenda."),
204	        RecusaDaPublicacao.UploadNaoEncontrado => new(
